export type FinanceOperationsMode = "overview" | "margins" | "billing" | "cash" | "collections" | "expenses";
type ExpenseLine = { id?: string; expense_date: string; nature: string; justification: string; supplier_name: string; project_id: string; amount_excluding_tax: string; vat_amount: string; amount_including_tax: string; receipt_status: string };

const supabase = createClient();
const txt = (value: unknown) => String(value ?? "").trim();
const num = (value: unknown) => Number(value || 0);
const euro = (value: unknown) => new Intl.NumberFormat("fr-FR", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(num(value));
const pct = (value: unknown) => `${new Intl.NumberFormat("fr-FR", { maximumFractionDigits: 1 }).format(num(value))} %`;
const month = (value: unknown) => value ? new Intl.DateTimeFormat("fr-FR", { month: "long", year: "numeric" }).format(new Date(`${txt(value).slice(0, 10)}T12:00:00`)) : "—";
const monthKey = (value: unknown) => txt(value).slice(0, 7);
const endOfMonth = (value: string) => { const [year, currentMonth] = value.split("-").map(Number); return new Date(Date.UTC(year, currentMonth, 0)).toISOString().slice(0, 10); };
const newLine = (): ExpenseLine => ({ expense_date: new Date().toISOString().slice(0, 10), nature: "Repas", justification: "", supplier_name: "", project_id: "", amount_excluding_tax: "", vat_amount: "", amount_including_tax: "", receipt_status: "missing" });

