  overview: { title: "Vue financière", subtitle: "Synthèse consolidée, sans formulaire ni double saisie, de la production à l’encaissement.", singular: "période" },
  margins: { title: "Valorisation & marges", subtitle: "Production et coûts par période ; marge, PCA et production non facturée calculés.", singular: "valorisation" },
  billing: { title: "Facturation & encaissements", subtitle: "Planification, émission, échéance, encaissement et écarts contractuels.", singular: "facturation" },
